insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x1-c1$qa$, $qa$pemweb-x1$qa$, $qa$checkpoint$qa$, $qa$Dalam model client-server, apa peran browser sebagai client?$qa$, $qa$["Menunggu permintaan lalu memproses database", "Memulai komunikasi, mengirim request, lalu menerima dan menampilkan response", "Menerjemahkan nama domain menjadi alamat IP", "Menyimpan data aplikasi secara permanen"]$qa$::jsonb, 1, $qa$Client (browser) memulai komunikasi: mengirim request, menerima response, dan menampilkannya.$qa$, 1) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x1-c2$qa$, $qa$pemweb-x1$qa$, $qa$checkpoint$qa$, $qa$Pada URL https://siakad.itera.ac.id/mhs#jadwal, bagian #jadwal disebut fragment. Apakah bagian ini dikirim ke server?$qa$, $qa$["Ya, dikirim bersama path", "Disimpan sementara di DNS resolver", "Tidak, hanya dipakai browser sebagai penunjuk bagian halaman", "Ya, dikirim sebagai query string"]$qa$::jsonb, 2, $qa$Fragment (#...) hanya penunjuk bagian halaman di browser dan tidak dikirim ke server.$qa$, 2) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x1-c3$qa$, $qa$pemweb-x1$qa$, $qa$checkpoint$qa$, $qa$Server mengembalikan status 404. Artinya...$qa$, $qa$["Server mengalami error internal", "Halaman dialihkan permanen", "Client meminta sumber daya yang tidak ditemukan", "Request berhasil diproses"]$qa$::jsonb, 2, $qa$4xx = client error; 404 Not Found berarti sumber daya yang diminta tidak ada.$qa$, 3) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x1-b1$qa$, $qa$pemweb-x1$qa$, $qa$battle$qa$, $qa$Pada URL https://siakad.itera.ac.id/mahasiswa?semester=2024, bagian ?semester=2024 disebut...$qa$, $qa$["Fragment", "Query string", "Path", "Subdomain"]$qa$::jsonb, 1, $qa$Query string diawali tanda ? dan berisi parameter kunci=nilai yang dikirim ke server.$qa$, 1) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x1-b2$qa$, $qa$pemweb-x1$qa$, $qa$battle$qa$, $qa$Metode HTTP yang paling tepat untuk mengirim data form login ke server adalah...$qa$, $qa$["GET, karena datanya terlihat di URL", "POST, karena data dikirim di body request", "DELETE, karena menghapus sesi lama", "PUT, karena memperbarui password"]$qa$::jsonb, 1, $qa$POST mengirim data di body request sehingga cocok untuk data sensitif seperti kredensial login.$qa$, 2) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
