insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x1-b5$qa$, $qa$pemweb-x1$qa$, $qa$battle$qa$, $qa$Perbedaan utama peran front-end developer dan back-end developer adalah...$qa$, $qa$["Front-end mengurus server, back-end mengurus tampilan", "Front-end membangun tampilan dan interaksi di browser, back-end mengolah logika server dan database", "Keduanya hanya mengurus database", "Back-end tidak menulis kode sama sekali"]$qa$::jsonb, 1, $qa$Front-end = sisi pengguna (HTML/CSS/JS di browser); back-end = sisi server (API, logika bisnis, database).$qa$, 5) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
